function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k.startsWith('on') && typeof v === 'function') {
      node.addEventListener(k.slice(2).toLowerCase(), v);
    } else if (k === 'className') {
      node.className = v;
    } else {
      node.setAttribute(k, v);
    }
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    node.append(typeof child === 'string' ? document.createTextNode(child) : child);
  }
  return node;
}

/* ─── State ─────────────────────────────────────────────────── */

let activeImage = null; // { name, src, size }

/* ─── Modal component ───────────────────────────────────────── */

function ModalDialog() {
  const overlay = el('div', {
    className: 'modal-overlay',
    role: 'dialog',
    'aria-modal': 'true',
    'aria-labelledby': 'modal-title',
    'aria-describedby': 'modal-desc',
  });

  const preview = el('img', {
    className: 'modal__preview',
    alt: '',
    'aria-hidden': 'true',
  });

  const imageNameSpan = el('strong', {});

  const description = el('p', {
    className: 'modal__desc',
    id: 'modal-desc',
  });

  function updateContent() {
    if (!activeImage) return;
    preview.src = activeImage.src;
    preview.alt = activeImage.name;
    imageNameSpan.textContent = activeImage.name;
    description.replaceChildren(
      document.createTextNode('Are you sure you want to permanently delete '),
      imageNameSpan,
      document.createTextNode(
        ' from your library? This action cannot be undone.'
      )
    );
  }

  function open(image) {
    activeImage = image;
    updateContent();
    overlay.classList.add('is-open');
    overlay.removeAttribute('aria-hidden');
    cancelBtn.focus();
    document.addEventListener('keydown', handleKeyDown);
  }

  function close() {
    overlay.classList.remove('is-open');
    overlay.setAttribute('aria-hidden', 'true');
    document.removeEventListener('keydown', handleKeyDown);
    if (pendingTrigger) {
      pendingTrigger.focus();
      pendingTrigger = null;
    }
  }

  function handleKeyDown(e) {
    if (e.key === 'Escape') close();
    if (e.key === 'Tab') trapFocus(e);
  }

  const focusableSelectors = 'button, [href], input, [tabindex]:not([tabindex="-1"])';

  function trapFocus(e) {
    const focusable = [...overlay.querySelectorAll(focusableSelectors)];
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  const cancelBtn = el(
    'button',
    { className: 'btn btn--cancel', type: 'button', onClick: close },
    'Cancel'
  );

  const deleteBtn = el(
    'button',
    {
      className: 'btn btn--confirm-delete',
      type: 'button',
      onClick: () => {
        if (activeImage) {
          removeCard(activeImage.id);
        }
        close();
      },
    },
    trashIcon(),
    'Delete image'
  );

  const modal = el(
    'div',
    { className: 'modal' },
    preview,
    el(
      'div',
      { className: 'modal__body' },
      el('div', { className: 'modal__icon', 'aria-hidden': 'true' }, trashIcon()),
      el('h2', { className: 'modal__title', id: 'modal-title' }, 'Delete image?'),
      description,
      el('div', { className: 'modal__actions' }, cancelBtn, deleteBtn)
    )
  );

  overlay.setAttribute('aria-hidden', 'true');
  overlay.append(modal);

  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) close();
  });

  return { node: overlay, open };
}

/* ─── Icon helpers ──────────────────────────────────────────── */

function trashIcon() {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
