    <path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/>
    <path d="M10 11v6M14 11v6"/>
    <path d="M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/>
  `;
  return svg;
}

function viewIcon() {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  svg.style.cssText = 'width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round';
  svg.innerHTML = `
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
    <circle cx="12" cy="12" r="3"/>
  `;
  return svg;
}

/* ─── Image card component ──────────────────────────────────── */

let pendingTrigger = null;

function ImageCard({ id, name, size, src }, modal) {
  function handleDelete(e) {
    pendingTrigger = e.currentTarget;
    modal.open({ id, name, size, src });
  }

  const card = el(
    'article',
    { className: 'image-card', id: `card-${id}` },
    el('img', {
      className: 'image-card__thumb',
      src,
      alt: name,
      loading: 'lazy',
    }),
    el(
      'div',
      { className: 'image-card__body' },
      el('p', { className: 'image-card__name' }, name),
      el('p', { className: 'image-card__meta' }, size),
      el(
        'div',
        { className: 'image-card__actions' },
        el(
          'button',
          { className: 'btn btn--secondary', type: 'button', 'aria-label': `View ${name}` },
          viewIcon(),
          'View'
        ),
        el(
          'button',
          {
            className: 'btn btn--danger trigger',
            type: 'button',
            'aria-label': `Delete ${name}`,
            onClick: handleDelete,
          },
          trashIcon2(),
          'Delete'
        )
      )
    )
  );

  return card;
}

function trashIcon2() {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('aria-hidden', 'true');
  svg.style.cssText = 'width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round';
  svg.innerHTML = `
    <polyline points="3 6 5 6 21 6"/>
    <path d="M19 6l-1 14a2 2 0 01-2 2H8a2 2 0 01-2-2L5 6"/>
    <path d="M10 11v6M14 11v6"/>
    <path d="M9 6V4a1 1 0 011-1h4a1 1 0 011 1v2"/>
  `;
  return svg;
}

/* ─── Card removal ───────────────────────────────────────────── */

function removeCard(id) {
  const card = document.getElementById(`card-${id}`);
  if (!card) return;
  card.style.transition = 'opacity 300ms ease, transform 300ms ease';
  card.style.opacity = '0';
  card.style.transform = 'scale(0.92)';
  setTimeout(() => card.remove(), 320);
}

